#include "stm32f411xe.h"
#include <stdint.h>
#include <stm32f4xx.h>

volatile uint8_t number = 0;
static void init_gpio(void);
static void init_exit13(void);

int main(void)
{
    // Hardware initialization code here
    init_gpio();
    init_exit13();

    while (1)
    {
        // Main loop code here
    }
    return 0;
}

void init_gpio(void)
{
    // Enable GPIOA clock
    RCC->AHB1ENR |= (1 << 2); // Enable GPIOC clock
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN_Msk; // Enable GPIOC clock

    // Configure PA13 as input
    GPIOC->MODER &= ~(0b11 << GPIO_MODER_MODE13_Pos); // Clear mode bits for PA13
    GPIOC->MODER |= (0b00 << GPIO_MODER_MODE13_Pos); // Set PA13 as general purpose input mode

    GPIOC->PUPDR |= (0b00 << GPIO_PUPDR_PUPD13_Pos); // No pull-up, pull-down for PA13
}

void init_exit13(void){
    // Enable SYSCFG clock
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN_Msk;

    // Configure EXTI line 13
    SYSCFG->EXTICR[3] &= ~(0b1111 << 4); // Clear EXTI13 configuration
    SYSCFG->EXTICR[3] |= (0b0010 << 4); // Select PA13 as source for EXTI13

    // Enable interrupt for EXTI13 on falling edge
    EXTI->FTSR |= (1 << 13); // Trigger on falling edge
    EXTI->IMR |= (1 << 13); // Unmask EXTI13

    NVIC_EnableIRQ(EXTI15_10_IRQn); // Enable EXTI15_10 interrupt in NVIC
}

void EXTI15_10_IRQHandler(void)
{
    if (EXTI->PR & (1 << 13)) // Check if EXTI13 triggered
    {
        // Handle the interrupt (e.g., toggle an LED, send a message, etc.)
        
        EXTI->PR |= (1 << 13); // Clear the pending interrupt flag for EXTI13
        number++; // Increment the number variable
    }   
}


